insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Какие виды нормативных правовых актов входят в понятие «трудовое законодательство»?$$,$$ст. 5Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Трудовой кодекс Российской Федерации, иные федеральные законы и законы субъектов Российской Федерации, содержащие нормы трудового права.$$,true),(qid,$$Трудовой кодекс Российской Федерации, иные федеральные законы, законы субъектов Российской Федерации, содержащие нормы трудового права, нормативные правовые акты федеральных органов исполнительной власти.$$,false),(qid,$$Трудовой кодекс Российской Федерации, иные федеральные законы, законы субъектов Российской Федерации, содержащие нормы трудового права, нормативные правовые акты федеральных органов исполнительной власти, нормативные правовые акты субъектов Российской федерации и нормативные правовые акты органов местного самоуправления.$$,false),(qid,$$Трудовой кодекс Российской Федерации, иные федеральные законы, законы субъектов Российской Федерации, содержащие нормы трудового права, нормативные правовые акты федеральных органов исполнительной власти и нормативные правовые акты субъектов Российской Федерации.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Какие виды нормативных правовых актов входят в понятие «иные нормативные правовые акты, содержащие нормы трудового права»?$$,$$ст. 5 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Указы Президента РФ, постановления Правительства РФ и нормативные правовые акты федеральных органов исполнительной власти.$$,false),(qid,$$Указы Президента РФ, постановления Правительства РФ, нормативные правовые акты федеральных органов исполнительной власти и нормативные правовые акты субъектов РФ.$$,false),(qid,$$Указы Президента РФ, постановления Правительства РФ, нормативные правовые акты федеральных органов исполнительной власти, нормативные правовые акты органов исполнительной власти субъектов РФ и нормативные правовые акты органов местного самоуправления.$$,true),(qid,$$Указы Президента РФ, постановления Правительства РФ, нормативные правовые акты федеральных органов исполнительной власти, нормативные правовые акты субъектов РФ, нормативные правовые акты органов местного самоуправления и локальные нормативные акты.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Что означает понятие «опасный производственный фактор» в соответствии с Трудовым кодексом Российской Федерации?$$,$$ст. 209Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Фактор производственной среды и трудового процесса, воздействие которого приводит к травме или смерти работника.$$,false),(qid,$$Производственный фактор, воздействие которого на работника в определённых условиях приводит к травме работника или другому внезапному резкому ухудшения его здоровья.$$,false),(qid,$$Фактор производственной среды или трудового процесса, воздействие которого может привести к травме или смерти работника.$$,true),(qid,$$Фактор производственной среды и трудового процесса, воздействие которого может привести к его травме.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Что означает понятие «опасность» в соответствии с Трудовым кодексом Российской Федерации?$$,$$ст. 209 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Фактор среды и трудового процесса, который может быть причиной травмы, острого заболевания или внезапного резкого ухудшения здоровья.$$,false),(qid,$$Сочетание вероятности причинения вреда и его тяжести.$$,false),(qid,$$Физическое повреждение или другой вред здоровью людей, имуществу или окружающей среде.$$,false),(qid,$$Потенциальный источник нанесения вреда, представляющий угрозу жизни и (или) здоровью работника в процессе трудовой деятельности.$$,true);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Кем на территории субъекта Российской Федерации осуществляется государственное управление охраной труда?$$,$$ст. 211 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Федеральными органами исполнительной власти и органами исполнительной власти субъекта Российской Федерации в области охраны труда в пределах их полномочий.$$,true),(qid,$$Органом, осуществляющим государственную экспертизу условий труда.$$,false),(qid,$$Органом исполнительной власти субъекта Российской Федерации в пределах его полномочий.$$,false),(qid,$$Государственной инспекцией труда в субъекте Российской Федерации.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Что означает понятие «система управления охраной труда» в соответствии Трудовым кодексом РФ?$$,$$ст. 217 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Комплекс взаимосвязанных и взаимодействующих между собой элементов, устанавливающих политику и цели в области охраны труда у конкретного работодателя и процедуры по достижению этих целей.$$,true),(qid,$$Совокупность взаимосвязанных и взаимодействующих между собой элементов системы управления, которая включает в себя организационную структуру, выполняющую функции управления по обеспечению охраны труда с использованием людских, технических и финансовых ресурсов.$$,false),(qid,$$Система обеспечения жизни и здоровья работников в процессе трудовой деятельности, включающая в себя правовые, социально-экономические, организационно-технические, санитарно-гигиенические, лечебно-профилактические, реабилитационные и иные мероприятия.$$,false),(qid,$$Совокупность мероприятий, направленных на сохранение жизни и здоровья работников в процессе трудовой деятельности.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Когда вступает в силу локальный нормативный акт?$$,$$ст. 12 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Со дня его принятия работодателем либо со дня, указанного в локальном нормативном акте.$$,true),(qid,$$Со дня, указанного в локальном нормативном акте.$$,false),(qid,$$Со дня, следующего за днём его принятия работодателем, либо со дня, указанного в локальном нормативном акте.$$,false),(qid,$$По истечении десяти дней после его утверждения работодателем.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$По каким вопросам, касающимся охраны труда, включаются в коллективный договор взаимные обязанности работников и работодателя?$$,$$ст. 41 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Обеспечение безопасных условий и охраны труда работников в процессе трудовой деятельности.$$,false),(qid,$$Сохранение жизни и здоровья работников при выполнении трудовой функции.$$,false),(qid,$$Гарантия работникам защиты их права на труд в условиях, соответствующих требованиям охраны труда.$$,false),(qid,$$Улучшение условий и охраны труда работников, в том числе женщин и молодежи.$$,true);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$В каком случае работодатель при принятии локальных нормативных актов учитывает мнение представительного органа работников (при наличии такого представительного органа)?$$,$$ст. 8 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Если это предусмотрено коллективным договором или соглашением.$$,true),(qid,$$Если это предусмотрено уставом представительного органа работников или положением об этом органе.$$,false),(qid,$$Инструкции по охране труда подлежат утверждению работодателем только по согласованию с указанным органом.$$,false),(qid,$$Если это предусмотрено правилами внутреннего трудового распорядка данной организации.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Кто имеет право осуществлять контроль за соблюдением трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права, а также за выполнением условий коллективных договоров, соглашений?$$,$$ст. 370Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Профессиональные союзы.$$,true),(qid,$$Государственные инспекции труда в субъектах.$$,false),(qid,$$Комитеты (комиссии) по охране труда.$$,false),(qid,$$Уполномоченные (доверенные лица) по охране труда профессиональных союзов.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Какие из нижеперечисленных актов являются носителями государственных нормативных требований охраны труда?$$,$$п. 2 Правил разработки, утверждения и изменения нормативных правовых актов федеральных органов исполнительной власти, содержащих государственные нормативные требования охраны труда, утв. Постановлением Правительства РФ от26.02.2022 № 255$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Межотраслевые правила и типовые инструкции по охране труда, государственные санитарно-эпидемиологические правила и нормативы (санитарные правила и нормы, санитарные нормы, санитарные правила и гигиенические нормативы, устанавливающие требования к факторам рабочей среды и трудового процесса).$$,false),(qid,$$Правила по охране труда, а также иные нормативные правовые акты, содержащие государственные нормативные требования охраны труда, единые типовые нормы бесплатной выдачи работникам средств индивидуальной защиты.$$,true),(qid,$$Правила по охране труда, государственные санитарно-эпидемиологические правила и нормативы (санитарные правила и нормы, санитарные нормы, санитарные правила и гигиенические нормативы, устанавливающие требования к факторам рабочей среды и трудового процесса), строительные нормы и правила, своды правил по проектированию и строительству.$$,false),(qid,$$Стандарты безопасности труда, межотраслевые правила и типовые инструкции по охране труда, государственные санитарно-эпидемиологические правила и нормативы (санитарные правила и нормы, санитарные нормы, санитарные правила и гигиенические нормативы, устанавливающие требования к факторам рабочей среды и трудового процесса).$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Кем в Российской Федерации осуществляется государственное управление охраной труда?$$,$$ст. 211Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Правительством РФ непосредственно или по его поручению федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере труда, а также другими федеральными органами исполнительной власти в пределах их полномочий.$$,true),(qid,$$Президентом РФ, Правительством РФ и федеральными органами исполнительной власти.$$,false),(qid,$$Президентом РФ, Правительством РФ, федеральными органами исполнительной власти, органами исполнительной власти субъектов РФ и органами местного самоуправления.$$,false),(qid,$$Правительством РФ, федеральными органами исполнительной власти, органами исполнительной власти субъектов РФ и органами местного самоуправления.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Какие основные принципы обеспечения безопасности труда установлены Трудовым кодексом Российской Федерации?$$,$$ст. 22-1Федерального закона от 30.12.201 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Сохранение жизни и здоровья работников в процессе трудовой деятельности.$$,false),(qid,$$Обеспечение жизни и здоровья работников в процессе трудовой деятельности.$$,false),(qid,$$Ликвидация производственных рисков или снижение их уровней и постоянная готовность работодателя к ликвидации последствий реализации производственных рисков.$$,false),(qid,$$Предупреждение и профилактика опасностей и минимизация повреждения здоровья работников.$$,true);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Где работодателю рекомендуется размещать Правила и инструкции по охране труда для работников?$$,$$п. 12 Рекомендации по размещению работодателем информационных материалов в целях информирования работников об их трудовых правах, утв. Приказом Министерство труда и социальной защиты РФ от 17.12.2021 № 894$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$В местах, специально отведённых и оборудованных для информирования работников –кабинетах или уголках по охране труда либо хранить в ином доступном для работников месте, определённом руководителем структурного подразделения, а также в электронном виде.$$,false),(qid,$$Непосредственно на рабочих местах или участках либо хранить в ином доступном для работников месте, определённом руководителем структурного подразделения, а также в электронном виде.$$,false),(qid,$$Непосредственно на рабочих местах или участках, в местах, специально отведённых и оборудованных для информирования работников – кабинетах или уголках по охране труда, а также в электронном виде.$$,false),(qid,$$Непосредственно на рабочих местах или участках, в местах, специально отведённых и оборудованных для информирования работников – кабинетах или уголках по охране труда, либо хранить в ином доступном для работников месте, определённом руководителем структурного подразделения, а также в электронном виде.$$,true);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$С какого возраста допускается заключение трудового договора?$$,$$ст. 63Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$С 16 лет для выполнения всех видов работ.$$,false),(qid,$$С 18 лет для выполнения всех видов работ, с 16 лет для выполнения легкого труда.$$,false),(qid,$$С16 лет для выполнения всех видов работ, с 15 лет для выполнения легкого труда, не причиняющего вреда их здоровью, с 14 лет для выполнения легкого труда с согласия одного из родителей, с не достигшими 14 лет на определенные трудовым законодательством работы только с согласия одного из родителей.$$,true),(qid,$$С 14 лет.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$В каких случаях работодатель обязан отстранить работника от работы (не допускать к работе)?$$,$$ст. 76Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Непрошедшего в установленном порядке обучение и проверку знаний и навыков в области охраны труда.$$,false),(qid,$$При появлении работника на работе в состоянии алкогольного, наркотического или иного токсического опьянения.$$,false),(qid,$$Непрошедшего в установленном порядке обязательного медосмотра, обязательного психиатрического освидетельствования.$$,false),(qid,$$При выявлении в соответствии медицинским заключением противопоказаний для выполнения работы.$$,false),(qid,$$Во всех перечисленных случаях.$$,true);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Какая максимальная продолжительность сверхурочной работы для каждого работника установлена ТК РФ?$$,$$ст. 99 Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$10 часов в течение недели и 150 часов в год.$$,false),(qid,$$4 часа в течение дня и 130 часов в год.$$,false),(qid,$$4 часа в течение двух дней подряд и 120 часов в год.$$,true),(qid,$$100 часов в год.$$,false);
