insert into answers(question_id,answer_text,is_correct) values (qid,$$Если он произошел с застрахованным или иным лицом, подлежащим обязательному социальному страхованию от несчастных случаев на производстве и профессиональных заболеваний.$$,true),(qid,$$Если он произошел на территории работодателя или при направлении по служебному заданию.$$,false),(qid,$$Если он произошел с застрахованным лицом и квалифицируется как несчастный случай связанный с производством.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Какой документ устанавливает государственные нормативные требования охраны труда при работе с устройствами, механизмами и иными средствами труда, используемыми для воздействия на предмет труда и его изменения, как перемещаемыми работником в ходе выполнения работ, таки установленными стационарно?$$,$$п. 1 Правил по охране труда при работе с инструментом и приспособлениями, утв. Приказом Министерство труда и социальной защиты от 27.11.2020 № 835н$$) returning id into qid;
