insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Кто обеспечивает разработку мер, направленных на обеспечение безопасных условий и охраны труда, оценку уровня профессиональных рисков перед вводом в эксплуатацию производственных объектов, вновь организованных рабочих мест?$$,$$ст. 214Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
