insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Категория работников, которые ежегодно проходят периодические медицинские осмотры?$$,$$ст. 220Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Для лиц в возрасте до 18 лет для определения пригодности этих работников для выполнения поручаемой работы и предупреждения профессиональных заболеваний.$$,false),(qid,$$Для лиц в возрасте до 21 года для определения пригодности этих работников для выполнения поручаемой работы и предупреждения профессиональных заболеваний..$$,true),(qid,$$Для лиц в возрасте 24 лет для определения пригодности этих работников для выполнения поручаемой работы и предупреждения профессиональных заболеваний.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$За счет кого осуществляются медицинские осмотры и психиатрические освидетельствования?$$,$$ст.220Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
