insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Кто имеет право запрещать использование средств индивидуальной и коллективной защиты работников, если такие средства не соответствуют обязательным требованиям, установленным в соответствии с законодательством Российской Федерации о техническом регулировании, и государственным нормативным требованиям охраны труда?$$,$$ст. 357Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Государственные инспекторы труда при осуществлении федерального государственного контроля (надзора).$$,true),(qid,$$Работник органа первичной профсоюзной организации.$$,false),(qid,$$Работник Фонда социального страхования Российской Федерации.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Вправе ли работник присутствовать при проведении специальной оценки условий труда на его рабочем месте?$$,$$ст. 5Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Да, работник имеет право присутствовать при проведении специальной оценки условий руда на всех рабочих, расположенных в подразделении.$$,false),(qid,$$Да, работник имеет право присутствовать при проведении специальной оценки условий, но только на своём рабочем месте.$$,true),(qid,$$Нет, на рабочем месте при проведении специальной оценки условий присутствует только представитель организации, проводящей специальную оценку условий труда.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Каждый работник имеет право на:$$,$$ст. 216Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
