insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$На время проведения медицинского осмотра за работниками, обязанными в соответствии с Трудовым кодексом РФ проходить медицинский осмотр:$$,$$ст. 185Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Сохраняется место работы и не менее 2/3 среднего заработка по месту работы.$$,false),(qid,$$Сохраняются место работы (должность) и средний заработок по месту работы.$$,true),(qid,$$Не сохраняется средний заработок по месту работы.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Имеет ли право работник на личное участие или участие через своих представителей в рассмотрении причин и обстоятельств событий, приведших к возникновению микроповреждений (микротравм)?$$,$$Рекомендации по учету микроповреждений (микротравм) работников, утв. Приказом Министерства труда и социальной защиты от 15.09.2021 № 632н$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Работник не принимает участие в рассмотрении причин микроповреждений (микротравм).$$,false),(qid,$$Работник имеет право на личное участие или участие через своих представителей.$$,true),(qid,$$Работник может только обратиться к своему непосредственному или вышестоящему руководителю и сообщить о микротравме.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Каждый работник имеет право на:$$,$$ст. 216Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Правильное использование производственного оборудования, инструмента, сырья и материалов.$$,false),(qid,$$Внеочередной медицинский осмотр в соответствии с нормативными правовыми актами и(или) медицинскими рекомендациями с сохранением за ним места работы (должности) и среднего заработка на время прохождения указанного медицинского осмотра.$$,true),(qid,$$Соблюдение требований охраны труда.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Повышенные или дополнительные гарантии и компенсации работникам, занятым на работах с вредными и (или)опасными условиями труда, могут устанавливаться:$$,$$ст. 216Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Коллективным договором по согласованию с комиссией по проведению специальной оценки условий труда.$$,false),(qid,$$Коллективным договором, локальным нормативным актом с учетом финансово-экономического положения работодателя.$$,true),(qid,$$Локальным нормативным актом по согласованию с государственным инспектором труда и органами исполнительной власти субъекта Российской Федерации в области охраны труда.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$В случае причинения вреда жизни и здоровью работника при исполнении им трудовых обязанностей возмещение указанного вреда осуществляется в рамках:$$,$$ст. 216Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Обязательного социального страхования от несчастных случаев на производстве и профессиональных заболеваний.$$,true),(qid,$$Личного страхование здоровья работника.$$,false),(qid,$$Выплат гарантий и компенсаций, установленных по результатам специальной оценки условий труда.$$,false);
insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Имеет ли право работник на получение смывающих средств по установленным нормам?$$,$$ст.216Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
