insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Условия труда, предусмотренные трудовым договором, должны соответствовать:$$,$$ст. 216-1Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
