insert into questions(category,question_text,explanation) values($$Основы охраны труда в Российской Федерации$$,$$Дайте определение понятию «коллективный договор»:$$,$$ст. 40Федерального закона от 30.12.2001 №197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
