insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Каков срок хранения акта о случае профессионального заболевания вместе с материалами расследования?$$,$$п. 32 Порядка расследования и учета случаев профессиональных заболеваний работников, утв. Постановлением Правительства РФ от 05.07.2022 № 1206$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$В течение 45 лет в центре государственного санитарно-эпидемиологического надзора и в организации, где проводилось расследование профессионального заболевания.$$,false),(qid,$$В течение 25 лет в центре государственного санитарно-эпидемиологического надзора и в организации, где проводилось расследование профессионального заболевания.$$,false),(qid,$$В течение 75 лет в центре государственного санитарно-эпидемиологического надзора и в организации, где проводилось расследование профессионального заболевания.$$,true);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$При групповом несчастном случае (два человека и более), тяжелом несчастном случае или несчастном случае со смертельным исходом, в течение какого времени работодатель (его представитель) обязан направить извещение по установленной форме?$$,$$ст. 228.1 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
