insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$На какой максимальный срок может быть продлено расследование несчастного случая при возникновении обстоятельств, объективно препятствующих завершению расследования несчастного случая, происшедшего в отдельных отраслях и организациях, в установленные статьей 229.1 Кодекса сроки, в том числе по причинам отдаленности и труднодоступности места происшествия, а также при необходимости дополнительного получения соответствующих медицинских и иных документов и заключений?$$,$$п. 19 Положения об особенностях расследования несчастных случаев на производстве в отдельных отраслях и организациях, форм документов, соответствующих классификаторов, необходимых для расследования несчастных случаев на производстве, утв. Приказом Министерства труда и социальной защиты от 20.04.2022 № 223н.$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Три рабочих дня.$$,false),(qid,$$Сутки.$$,false),(qid,$$Три календарных дня.$$,true),(qid,$$Пятнадцать календарных дней.$$,false),(qid,$$Месяц.$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Как исчисляются сроки расследования несчастных случаев?$$,$$п. 22 Положения об особенностях расследования несчастных случаев на производстве в отдельных отраслях и организациях, форм документов, соответствующих классификаторов, необходимых для расследования несчастных случаев на производстве, утв. Приказом Министерства труда и социальной защиты от 20.04.2022 № 223н.$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$В рабочих днях, начиная со дня получении сообщения о происшедшем несчастном случае.$$,false),(qid,$$В рабочих днях, начиная со дня издания работодателем приказа об образовании комиссии по расследованию несчастного случая.$$,false),(qid,$$В календарных днях, начиная со дня получении сообщения о происшедшем несчастном случае.$$,false),(qid,$$Не позднее одного месяца со дня получении сообщения о происшедшем несчастном случае.$$,false),(qid,$$В календарных днях, начиная со дня издания работодателем приказа об образовании комиссии по расследованию несчастного случая.$$,true);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$В какой срок после получения сведений о несчастных случаях, которые по прошествии времени перешли в категорию тяжелых несчастных случаев или несчастных случаев со смертельным исходом, работодатель (его представитель) направляет извещение по установленной форме в соответствующие территориальный орган федерального органа исполнительной власти?$$,$$ст. 228.1 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
