insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Найдите наиболее точное определение микротравмы согласно ТК РФ:$$,$$Федеральный закон от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Повреждение, вызванное каким-либо воздействием, обычно незначительным по своей силе, но превышающим пределы физиологического сопротивления тканей и приводящим к нарушению функции и структуры тканей после однократного или многократного однотипного его воздействия.$$,false),(qid,$$Ссадины, кровоподтеки, ушибы мягких тканей, поверхностные раны и другие повреждения, полученные работниками и другими лицами, участвующими в производственной деятельности работодателя, указанными в части второй статьи 227 настоящего Кодекса, при исполнении ими трудовых обязанностей или выполнении какой-либо работы по поручению работодателя (его представителя), а также при осуществлении иных правомерных действий, обусловленных трудовыми отношениями с работодателем либо совершаемых в его интересах, не повлекшие расстройства здоровья или наступление временной нетрудоспособности.$$,true),(qid,$$Это микроповреждения здоровья работников организации во время выполнения работы или поручений руководителя. Это незначительные повреждения, которые приводят к частичному ограничению трудоспособности работника, возможно, даже потребуется перевести пострадавшего сотрудника на один день на другую работу, но больничный лист при этом не открывается.$$,false),(qid,$$Постепенный износ организма в результате ежедневных нагрузок.$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Обязан ли работодатель вести учет микроповреждений (микротравм) работников?$$,$$ст. 226 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Обязан.$$,true),(qid,$$Не обязан.$$,false),(qid,$$По усмотрению специалиста по охране труда.$$,false),(qid,$$По усмотрению профсоюзного комитета.$$,false),(qid,$$По усмотрению государственного инспектора по охране труда.$$,false),(qid,$$В зависимости от степени повреждений и последующих последствий для профессиональной деятельности.$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$В какие сроки выплачиваются застрахованным от несчастных случаев на производстве и профессиональных заболеваний единовременные страховые выплаты?$$,$$ст. 10 Федерального закона от 24.07.1998 №125 "Об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний"$$) returning id into qid;
