insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$В какой срок расследуется несчастный случай, о котором не было своевременно сообщено работодателю или в результате которого нетрудоспособность наступила не сразу?$$,$$ст. 229.1 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
