insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Какие установлены сроки расследования несчастного случая (в том числе группового), в результате которого один или несколько пострадавших получили тяжелые повреждения здоровья, либо несчастного случая (в том числе группового) со смертельным исходом?$$,$$ст. 229.1 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
