insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Кем устанавливается степень вины застрахованного в процентах, если при расследовании несчастного случая установлено, что грубая неосторожность застрахованного содействовала возникновению или увеличению вреда, причиненного его здоровью?$$,$$Ст.14 Федерального закона от 24.07.1998 N 125-ФЗ "Об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний".$$) returning id into qid;
