insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Какой вид инструктажа по охране труда проводится после расследования несчастного случая на производстве:$$,$$Постановление Правительства РФ от 24.12.2021 №2464 «О порядке обучения по охране труда и проверки знания требований охраны труда».$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Повторный инструктаж по охране труда$$,false),(qid,$$Первичный инструктаж по охране труда$$,false),(qid,$$Вводный инструктаж$$,false),(qid,$$Внеплановый инструктаж по охране труда$$,true);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Кто формирует комиссию и расследует несчастный случай, происшедший с лицом, направленным для выполнения работы к другому работодателю и участвовавшим в его производственной деятельности?$$,$$ст. 229 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
