insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Какой акт оформляется по результатам расследования несчастного случая на производстве, из-за которого потребовалось перевести пострадавшего на другую работу в соответствии с выданным в установленном порядке медзаключением, либо он потерял трудоспособность не менее чем на один день, либо умер?$$,$$Приложение 2 Положения об особенностях расследования несчастных случаев на производстве в отдельных отраслях и организациях, форм документов, соответствующих классификаторов, необходимых для расследования несчастных случаев на производстве, утв. Приказом Министерства труда и социальной защиты от 20.04.2022 № 223н$$) returning id into qid;
