insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$При выполнении трудовых обязанностей работник получил травму, которая потребовала его госпитализации (тяжелый несчастный случай). В какой срок работодатель обязан проинформировать о данном несчастном случае установленные законодательством органы и организации, а также родственников пострадавшего?$$,$$ст.2278.1 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
