insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Положение об особенностях расследования несчастных случаев на производстве в отдельных отраслях и организациях.., утв. Приказом Минтруда России от 20.04.2022 N 223н обязательно для применения:$$,$$ст. 214; 229.2 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
