insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$В течение, какого срока с даты получения извещения об установлении заключительного диагноза профессионального заболевания работодатель образует комиссию по расследованию профессионального заболевания?$$,$$п. 15 Порядка расследования и учета случаев профессиональных заболеваний работников, утв. Постановлением Правительства РФ от 05.07.2022 № 1206.$$) returning id into qid;
