insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Какой документ обязан издать работодатель в месячный срок после завершения расследования профессионального заболевания на основании акта о случае профессионального заболевания?$$,$$Порядок расследования и учета случаев профессиональных заболеваний работников, утв. Постановлением Правительства РФ от 05.07.2022 № 1206$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Направить заявление в органы исполнительной власти субъектов Российской Федерации в области охраны труда на проведение государственной экспертизы условий труда.$$,false),(qid,$$Издать приказ о конкретных мерах по предупреждению профессиональных заболеваний.$$,true),(qid,$$Разработать мероприятия по улучшению условий труда.$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Что такое профессиональное заболевание?$$,$$ст. 2 Федерального закона от 24.07.1998 №125 "Об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Хроническое или острое заболевание застрахованного, являющееся результатом воздействия на него вредного (вредных) производственного (производственных) фактора (факторов) и повлекшее временную или стойкую утрату им профессиональной трудоспособности и (или) его смерть.$$,true),(qid,$$Состояние физического, психического и социального благополучия человека, при котором отсутствуют заболевания, а также расстройства функций органов и систем организма.$$,false),(qid,$$Возникающее в связи с воздействием патогенных факторов нарушение деятельности организма, работоспособности, способности адаптироваться к изменяющимся условиям внешней и внутренней среды при одновременном изменении защитно-компенсаторных и защитно-приспособительных реакций и механизмов организма.$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Что понимается под хроническим профессиональным заболеванием (отравлением)?$$,$$п. 2 Порядка расследования и учета случаев профессиональных заболеваний работников, утв. Постановлением Правительства РФ от 05.07.2022 № 1206$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Заболевание, являющееся, результатом однократного (в течение не более одного рабочего дня, одной рабочей смены) воздействия на работника вредного производственного фактора (факторов) и повлекшее временную или стойкую утрату профессиональной трудоспособности.$$,false),(qid,$$Заболевание, являющееся результатом длительного воздействия на работника вредного производственного фактора (факторов) и повлекшее временную или стойкую утрату профессиональной трудоспособности.$$,true),(qid,$$Заболевание, являющееся результатом кратковременного воздействия на работника вредного производственного фактора (факторов)и повлекшее временную или стойкую утрату профессиональной трудоспособности.$$,false);
