insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Где фиксируется выдача работникам индивидуальной защиты и сдача ими средств индивидуальной защиты?$$,$$Приказ Министерство труда и социальной защиты российской федерации от 29.10 2021 г. № 766н «Об утверждении правил обеспечения работников средствами индивидуальной защиты и смывающими средствами».$$) returning id into qid;
