insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Кем устанавливается степень тяжести травмы, полученной работником на производстве устанавливается?$$,$$п. 3 Положения об особенностях расследования несчастных случаев на производстве в отдельных отраслях и организациях, форм документов, соответствующих классификаторов, необходимых для расследования несчастных случаев на производстве, утв. Приказом Министерства труда и социальной защиты от 20.04.2022 № 223н$$) returning id into qid;
