insert into answers(question_id,answer_text,is_correct) values (qid,$$страховое возмещение вреда, причиненного в результате наступления страхового случая жизни и здоровью застрахованного, в виде денежных сумм, выплачиваемых либо компенсируемых страховщиком застрахованному или лицам, имеющим на это право в соответствии с Федеральным законом "Об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний"$$,true),(qid,$$обязательный платеж по обязательному социальному страхованию от несчастных случаев на производстве и профессиональных заболеваний, рассчитанный исходя из страхового тарифа, скидки (надбавки) к страховому тарифу, который страхователь обязан внести страховщику$$,false),(qid,$$ставка страхового взноса, исчисленная исходя из сумм выплат и иных вознаграждений, начисленных в пользу застрахованных по трудовым договорам и гражданско-правовым договорам и включаемых в базу для начисления страховых взносов$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Какое определение соответствует понятию «несчастный случай на производстве»?$$,null) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Хроническое или острое заболевание застрахованного, являющееся результатом воздействия на него вредного (вредных) производственного (производственных) фактора (факторов) и повлекшее временную или стойкую утрату им профессиональной трудоспособности и (или) его смерть.$$,false),(qid,$$Событие, в результате которого застрахованный получил увечье или иное повреждение здоровья при исполнении им обязанностей по трудовому договору и в иных установленных Федеральным законом "Об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний" случаях как на территории страхователя, так и за ее пределами либо во время следования к месту работы или возвращения с места работы на транспорте, предоставленном страхователем, и которое повлекло необходимость перевода застрахованного на другую работу, временную или стойкую утрату им профессиональной трудоспособности либо его смерть.$$,true),(qid,$$Выраженное в процентах стойкое снижение способности застрахованного осуществлять профессиональную деятельность до наступления страхового случая$$,false);
insert into questions(category,question_text,explanation) values($$Общие вопросы охраны труда и функционирования системы управления охраной труда (СУОТ)$$,$$Для чего работодателем (его представителем) с участием выборного органа первичной профсоюзной организации или иного уполномоченного представительного органа работников (при наличии такого представительного органа) рассматриваются результаты расследования несчастного случая на производстве?$$,$$ст. 230 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Принятия мер, направленных на предупреждение несчастных случаев на производстве.$$,true),(qid,$$Планирования работы специалиста по охране труда по предотвращению несчастных случаев на производстве.$$,false),(qid,$$Для вынесения профсоюзного порицания нарушителям.$$,false),(qid,$$Для укрепления трудовой дисциплины.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$На какие классы подразделяются условия труда на рабочих местах по степени вредности и (или) опасности?$$,$$ст. 14 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Допустимые, вредные и опасные.$$,false),(qid,$$Оптимальные, допустимые, вредные и опасные.$$,true),(qid,$$Оптимальные, допустимые, вредные и очень вредные.$$,false),(qid,$$В пределах нормативных значений, вредные и опасные.$$,false),(qid,$$Нет правильного ответа.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какими являются условия труда, при которых воздействие на работника вредных и (или) опасных производственных факторов отсутствует или уровни воздействия которых не превышают уровни, установленные нормативами (гигиеническими нормативами) условий труда?$$,$$ст. 14 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Оптимальными.$$,true),(qid,$$Допустимыми.$$,false),(qid,$$В пределах нормативных значений.$$,false),(qid,$$Вредными.$$,false),(qid,$$Опасными.$$,false),(qid,$$Вне пределов нормативных значений.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какими являются условия труда, при которых на работника воздействуют вредные и (или) опасные производственные факторы, уровни воздействия которых не превышают уровни, установленные нормативами (гигиеническими нормативами) условий труда?$$,$$ст. 14 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Оптимальными.$$,false),(qid,$$Допустимыми.$$,true),(qid,$$В пределах нормативных значений.$$,false),(qid,$$Вредными.$$,false),(qid,$$Опасными.$$,false),(qid,$$Вне пределов нормативных значений.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какими являются условия труда, при которых уровни воздействия вредных и (или) опасных производственных факторов превышают уровни, установленные нормативами (гигиеническими нормативами) условий труда?$$,$$ст. 14 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Оптимальными.$$,false),(qid,$$Допустимыми.$$,false),(qid,$$В пределах нормативных значений.$$,false),(qid,$$Вредными.$$,true),(qid,$$Опасными.$$,false),(qid,$$Вне пределов нормативных значений.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$В какой срок работодатель организует ознакомление работников с результатами проведения специальной оценки условий труда на их рабочих местах?$$,$$ст. 15 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Не более тридцати календарных дней.$$,true),(qid,$$Не более тридцати рабочих дней.$$,false),(qid,$$Не более трех календарных дней.$$,false),(qid,$$Не более десяти рабочих дней.$$,false),(qid,$$Нет правильного ответа.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Что устанавливается на рабочих местах по результатам проведения специальной оценки условий труда? Что по результатам проведения специальной оценки условий труда устанавливается на рабочих местах?$$,$$ст. 3 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Категория (подкатегория) условий труда.$$,false),(qid,$$Класс опасности на рабочих местах.$$,false),(qid,$$Классы (подклассы) условий труда.$$,true),(qid,$$Уровень (подуровень) условий труда$$,false),(qid,$$Нет правильного ответа.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Кем принимается решение о возможности применения, в целях проведения специальной оценки условий труда, результатов исследований (испытаний) и измерений вредных и (или) опасных производственных факторов, проведенных при осуществлении на рабочих местах производственного контроля за условиями труда?$$,$$ст. 12 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Комиссией по проведению специальной оценки условий труда по представлению эксперта организации, проводящей специальную оценку условий труда.$$,true),(qid,$$Председателем первичной профсоюзной организации по представлению эксперта организации, проводящей специальную оценку условий труда.$$,false),(qid,$$Экспертом организации, проводящей специальную оценку условий труда.$$,false),(qid,$$Работодателем или его представителем по представлению Председателя первичной профсоюзной организации.$$,false),(qid,$$Нет правильного ответа.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Обязанностями работника в связи с проведением специальной оценки условий труда являются:$$,$$ст. 5 Федерального закона от 28.12.2013 № 426-ФЗ "О специальной оценки условий труда"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Присутствовать при проведении специальной оценки условий труда на его рабочем месте.$$,false),(qid,$$Обращаться к работодателю, его представителю, организации, проводящей специальную оценку условий труда, эксперту организации, проводящей специальную оценку условий труда, с предложениями по осуществлению на его рабочем месте идентификации потенциально вредных и (или) опасных производственных факторов и за получением разъяснений по вопросам проведения специальной оценки условий труда на его рабочем месте.$$,false),(qid,$$Обжаловать результаты проведения специальной оценки условий труда на его рабочем месте в соответствии со статьей 26 N 426-ФЗ от 28.12.2013 «О специальной оценке условий труда».$$,false),(qid,$$Ознакомиться с результатами проведенной на его рабочем месте специальной оценки условий труда.$$,true);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$К какому виду опасностей относится электрический ток?$$,$$Рекомендации по классификации, обнаружению, распознаванию и описанию опасностей, утв. Приказом Минтруда России от 31.01.2022г. № 36$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Химические опасности.$$,false),(qid,$$Механические опасности.$$,false),(qid,$$Эргономические опасности.$$,false),(qid,$$Физические опасности.$$,true),(qid,$$Психологические опасности.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Каково максимальное время проведения работ в ограниченных замкнутых пространствах (ОЗП) с использованием шлангового противогаза?$$,$$п. 33 Правил по охране труда при работе в ограниченных и замкнутых пространствах, утв. Приказом Минтруда России от 15.12.2020г. № 902н$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Не более 20 мин.$$,false),(qid,$$Не более 30 мин.$$,true),(qid,$$Не более 15 мин.$$,false),(qid,$$Не более 40 мин.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$При использовании, какого из представленных СИЗОД время работы не должны превышать 30 минут с последующим отдыхом не менее 15 минут?$$,$$п. 33 Правил по охране труда при работе в ограниченных и замкнутых пространствах, утв. Приказом Минтруда России от 15.12.2020г. № 902н$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Дыхательный аппарат на сжатом воздухе.$$,false),(qid,$$Шланговый противогаз.$$,true),(qid,$$Самоспасатель изолирующего типа.$$,false),(qid,$$Противогаз фильтрующий.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какое определение СИЗ является верным: «Средство индивидуальной защиты – это ...»$$,$$ст. 209 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Средство, используемое для предотвращения воздействия на работника вредных и (или) опасных производственных факторов, особых температурных условий, а также для защиты от загрязнения.$$,false),(qid,$$Средство, используемое для уменьшения воздействия на работника вредных и (или) опасных производственных факторов, особых температурных условий, а также для защиты от загрязнения.$$,false),(qid,$$Средство, используемое для предотвращения или уменьшения воздействия на работника вредных и (или) опасных производственных факторов.$$,false),(qid,$$Средство, используемое для предотвращения или уменьшения воздействия на работника вредных и (или) опасных производственных факторов, особых температурных условий, а также для защиты от загрязнения.$$,true);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$При проведении, каких работ работодатель обязан обеспечить приобретение и выдачу работникам средств индивидуальной защиты и смывающих средств?$$,$$ст. 214 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$На работах с вредными и (или) опасными условиями труда.$$,false),(qid,$$На работах, выполняемых в особых температурных условиях.$$,false),(qid,$$На работах, связанных с загрязнением.$$,false),(qid,$$На работах с вредными и (или) опасными условиями труда, а также на работах, выполняемых в особых температурных условиях или связанных с загрязнением.$$,true);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какие средства индивидуальной защиты должны изготавливаться из материалов, исключающих искрообразование?$$,$$п. 4.2 ТР ТС 019/2011 "О безопасности средств индивидуальной защиты"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Все средства индивидуальной защиты.$$,false),(qid,$$Средства индивидуальной защиты, предназначенные для использования в пожаровзрывоопасной среде.$$,true),(qid,$$Средства индивидуальной защиты, используемые подразделениями пожарной охраны.$$,false),(qid,$$Средства индивидуальной защиты, используемые при эксплуатации электроустановок.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Что должно быть указано в эксплуатационной документации к средствам индивидуальной защиты?$$,$$п. 4.2 ТР ТС 019/2011 "О безопасности средств индивидуальной защиты"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Комплектность, срок хранения или годности, гарантийный срок (для средств индивидуальной защиты, теряющих защитные свойства в процессе хранения и (или) эксплуатации), правила безопасного хранения, использования (эксплуатации и ухода), транспортировки и утилизации, а также при необходимости климатическое исполнение средств индивидуальной защиты и правила их дегазации, дезактивации, дезинфекции, а также способы подтверждения их защитных свойств.$$,true),(qid,$$Правила безопасного хранения, использования (эксплуатации и ухода), транспортировки и утилизации.$$,false),(qid,$$Правила дегазации, дезактивации, дезинфекции средств индивидуальной защиты.$$,false),(qid,$$Климатическое исполнение средств индивидуальной защиты.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какое значение времени надевания и приведения в действие должно составлять у фильтрующего самоспасателя, используемого при пожарах?$$,$$п. 4.4 ТР ТС 019/2011 "О безопасности средств индивидуальной защиты"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Не более 60 с.$$,true),(qid,$$Не более 90 с.$$,false),(qid,$$Не более 120 с.$$,false),(qid,$$Не более 180 с.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Какая бывает форма подтверждения соответствия средств индивидуальной защиты требованиям технического регламента Таможенного союза?$$,$$п. 5.4 ТР ТС 019/2011 "О безопасности средств индивидуальной защиты"$$) returning id into qid;
insert into answers(question_id,answer_text,is_correct) values (qid,$$Декларирование соответствия.$$,false),(qid,$$Сертификация.$$,false),(qid,$$Декларирование соответствия и сертификация.$$,true),(qid,$$Уведомление.$$,false);
insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$За чей счет работник обеспечивается средствами индивидуальной защиты?$$,$$ст. 214 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации"$$) returning id into qid;
