insert into questions(category,question_text,explanation) values($$Безопасные методы и приемы выполнения работ повышенной опасности$$,$$Обязан ли работник при увольнении вернуть средства индивидуальной защиты работодателю?$$,$$ст. 212 Федерального закона от 30.12.2001 № 197-ФЗ "Трудовой Кодекс Российской Федерации".$$) returning id into qid;
