insert into answers(question_id,answer_text,is_correct) values (qid,$$Размещение химических веществ должно осуществляться в соответствии с объемом поступающих химических веществ на склад - в порядке убывания объема от главного въезда на склад$$,false),(qid,$$При выполнении складских работ с химическими веществами следует постоянно следить за параметрами микроклимата: не допускать понижения температуры или влажности больше чем на 20% от допустимых значений$$,false),(qid,$$Химические вещества, поступающие без тары (навалом), должны храниться в плотно закрывающихся закромах, ларях, бункерах, которые должны иметь различимые надписи с указанием названий веществ$$,true),(qid,$$При обнаружении повреждений тары (упаковки) с химическими веществами складские работы следует продолжать с особой аккуратностью во избежание россыпи химических веществ.$$,false);
