insert into answers(question_id,answer_text,is_correct) values (qid,$$Если работы периодически повторяются, являются частью производственного процесса, характеризуются постоянством места, условий и характера, проводятся постоянным составом квалифицированных исполнителей$$,true),(qid,$$Если работы выполняют работники не моложе 21 года, прошедшие предварительный медицинский осмотр и имеющие удостоверение на право производства работ$$,false),(qid,$$Если работы являются продолжением или завершением работ, на которые был оформлен наряд-допуск, после окончания срока его действия$$,false),(qid,$$Ни в каком случае$$,false);
