insert into answers(question_id,answer_text,is_correct) values (qid,$$Оценить сознание, при его отсутствии оценить наличие дыхания, при отсутствии дыхания поручить помощнику вызвать скорую медицинскую помощь, приступить к сердечно-легочной реанимации.$$,true),(qid,$$Определить наличие пульса и реакции зрачков на свет, при их отсутствии – очистить ротовую полость, повернув голову пострадавшего набок, приступить к сердечно-легочной реанимации.$$,false),(qid,$$Проверить наличие признаков жизни, при их отсутствии поручить помощнику вызвать скорую медицинскую помощь, перекинуть пострадавшего через свое бедро лицом вниз, дождаться окончания выделения воды из его рта, положить пострадавшего на спину, приступить к сердечно-легочной реанимации.$$,false),(qid,$$Тщательно очистить ротовую полость и полость ротоглотки от ила, водорослей и других возможных загрязнений, приступить к сердечно-легочной реанимации, по окончании реанимации доставить пострадавшего в медицинскую организацию.$$,false);
